CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE sqlite_sequence(name,seq);
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE TABLE IF NOT EXISTS "users" ("id" varchar not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "timezone" varchar, "created_at" datetime, "updated_at" datetime, "role" varchar not null default 'user', "is_active" tinyint(1) not null default '1', "last_login_at" datetime, "avatar_url" varchar, "bio" text, "email_notifications" tinyint(1) not null default '1', "push_notifications" tinyint(1) not null default '1', "notification_frequency" varchar check ("notification_frequency" in ('instant', 'daily', 'weekly')) not null default 'instant', "failed_login_attempts" integer not null default '0', "locked_until" datetime, "two_factor_secret" text, "two_factor_recovery_codes" text, "two_factor_confirmed_at" datetime, "verification_token" varchar, "verification_expires_at" datetime, "remember_token" varchar, primary key ("id"));
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE TABLE IF NOT EXISTS "subjects" ("id" varchar not null, "user_id" varchar not null, "name" varchar not null, "exam_date" date not null, "priority_level" integer not null default '3', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, primary key ("id"));
CREATE TABLE IF NOT EXISTS "topics" ("id" varchar not null, "subject_id" varchar not null, "title" varchar not null, "difficulty" integer not null default '3', "estimated_hours" float, "is_completed" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("subject_id") references "subjects"("id") on delete cascade, primary key ("id"));
CREATE TABLE IF NOT EXISTS "daily_plans" ("id" varchar not null, "user_id" varchar not null, "plan_date" date not null, "total_hours" float, "ai_version" varchar, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, primary key ("id"));
CREATE UNIQUE INDEX "daily_plans_user_id_plan_date_unique" on "daily_plans" ("user_id", "plan_date");
CREATE TABLE IF NOT EXISTS "daily_tasks" ("id" varchar not null, "daily_plan_id" varchar not null, "topic_id" varchar not null, "task_title" varchar not null, "planned_minutes" integer, "task_order" integer, "status" varchar not null default 'pending', "created_at" datetime, "updated_at" datetime, foreign key("daily_plan_id") references "daily_plans"("id") on delete cascade, foreign key("topic_id") references "topics"("id") on delete cascade, primary key ("id"));
CREATE TABLE IF NOT EXISTS "progress_logs" ("id" varchar not null, "user_id" varchar not null, "topic_id" varchar not null, "log_date" date not null, "minutes_studied" integer not null, "completion_status" varchar not null, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("topic_id") references "topics"("id") on delete cascade, primary key ("id"));
CREATE TABLE IF NOT EXISTS "ai_feedback" ("id" varchar not null, "user_id" varchar not null, "plan_date" date not null, "input_summary" text, "ai_response_summary" text, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, primary key ("id"));
CREATE TABLE IF NOT EXISTS "files" ("id" varchar not null, "user_id" varchar not null, "filename" varchar not null, "original_name" varchar not null, "url" text not null, "storage_path" varchar, "size" integer not null, "mime_type" varchar not null, "file_type" varchar not null, "cloud_public_id" varchar, "metadata" text, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, primary key ("id"));
CREATE INDEX "files_user_id_index" on "files" ("user_id");
CREATE INDEX "files_file_type_index" on "files" ("file_type");
CREATE TABLE IF NOT EXISTS "notifications" ("id" varchar not null, "user_id" varchar not null, "type" varchar not null, "title" varchar not null, "message" text not null, "data" text, "action_url" varchar, "is_read" tinyint(1) not null default '0', "read_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, primary key ("id"));
CREATE INDEX "notifications_user_id_is_read_index" on "notifications" ("user_id", "is_read");
CREATE INDEX "notifications_created_at_index" on "notifications" ("created_at");
CREATE TABLE IF NOT EXISTS "analytics_events" ("id" varchar not null, "user_id" varchar, "session_id" varchar, "event" varchar not null, "category" varchar, "properties" text, "page_url" varchar, "referrer" varchar, "user_agent" varchar, "ip_address" varchar, "created_at" datetime not null, foreign key("user_id") references "users"("id") on delete set null, primary key ("id"));
CREATE INDEX "analytics_events_user_id_event_index" on "analytics_events" ("user_id", "event");
CREATE INDEX "analytics_events_event_created_at_index" on "analytics_events" ("event", "created_at");
CREATE INDEX "analytics_events_session_id_index" on "analytics_events" ("session_id");
CREATE TABLE IF NOT EXISTS "transactions" ("id" varchar not null, "user_id" varchar not null, "stripe_payment_id" varchar not null, "amount" integer not null, "currency" varchar not null, "status" varchar not null, "metadata" text, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, primary key ("id"));
CREATE UNIQUE INDEX "transactions_stripe_payment_id_unique" on "transactions" ("stripe_payment_id");
CREATE TABLE IF NOT EXISTS "chat_messages" ("id" varchar not null, "user_id" varchar not null, "study_material_id" varchar not null, "role" varchar check ("role" in ('user', 'assistant')) not null, "content" text not null, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("study_material_id") references "study_materials"("id") on delete cascade, primary key ("id"));
CREATE TABLE IF NOT EXISTS "study_materials" ("id" varchar not null, "user_id" varchar not null, "subject_id" varchar, "file_id" varchar not null, "title" varchar not null, "document_type" varchar not null default ('document'), "content_extracted" text, "ai_analysis" text, "status" varchar not null default ('pending'), "created_at" datetime, "updated_at" datetime, foreign key("file_id") references files("id") on delete cascade on update no action, foreign key("subject_id") references subjects("id") on delete cascade on update no action, foreign key("user_id") references users("id") on delete cascade on update no action, primary key ("id"));
